const updateWorkSession = `-- name: UpdateWorkSession :exec
UPDATE work_session SET state= $1,changed_at= $2,ended_at=$3,
active_ms= $4,waiting_ms= $5,reported_active_ms=$6,
outcome=$7,result=$8,tokens=$9,note= $10,incomplete= $11
WHERE id= $12
`

type UpdateWorkSessionParams struct {
	State            string
	ChangedAt        time.Time
	EndedAt          *time.Time
	ActiveMs         int64
	WaitingMs        int64
	ReportedActiveMs pgtype.Int8
	Outcome          pgtype.Text
	Result           pgtype.Text
	Tokens           pgtype.Int8
	Note             string
	Incomplete       bool
	ID               string
}

func (q *Queries) UpdateWorkSession(ctx context.Context, arg UpdateWorkSessionParams) error {
	_, err := q.db.Exec(ctx, updateWorkSession,
		arg.State,
		arg.ChangedAt,
		arg.EndedAt,
		arg.ActiveMs,
		arg.WaitingMs,
		arg.ReportedActiveMs,
		arg.Outcome,
		arg.Result,
		arg.Tokens,
		arg.Note,
		arg.Incomplete,
		arg.ID,
	)
	return err
}

const workRequiresRegistration = `-- name: WorkRequiresRegistration :one
SELECT EXISTS(SELECT 1 FROM work_session s JOIN work_allocation a ON a.session_id=s.id
WHERE a.ticket_id= $1 AND s.actor_id= $2 AND s.policy->>'require_registration'='true')
`

type WorkRequiresRegistrationParams struct {
	TicketID string
	ActorID  string
}

func (q *Queries) WorkRequiresRegistration(ctx context.Context, arg WorkRequiresRegistrationParams) (bool, error) {
	row := q.db.QueryRow(ctx, workRequiresRegistration, arg.TicketID, arg.ActorID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}
